    public static final BlockPos A=new BlockPos(8,207,8),B=new BlockPos(24,207,8),T=new BlockPos(8,205,24),J=T.east(2);
    static final UUID ID=UUID.fromString("e1024f82-cb04-4fa0-b476-6b5d1b559d12");static ServerPlayer owner;static int waiting;static String pending="";
